SELECT departments.id, departments.location, departments.budget, t.unique_depts, t.pct_manager FROM departments LEFT JOIN (SELECT dept_id, COUNT(DISTINCT salary) AS unique_depts, ROUND((100 * SUM(CASE WHEN job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager FROM employees WHERE job_title NOT IN ('Designer', 'Manager', 'Intern') GROUP BY dept_id) t ON departments.id = t.dept_id
